function cdqPdfDriveUrlV2282(id){
  id=String(id||'');
  if(!/^[A-Za-z0-9_-]+$/.test(id))throw new Error('Identifiant PDF invalide.');
  return 'https://drive.google.com/file/d/'+id+'/view?usp=drivesdk';
}
function cdqPdfDriveAppUrlV2283(id,reader){
  id=String(id||'');
  const url=cdqPdfDriveUrlV2282(id);

  if(!/Android/i.test(navigator.userAgent||''))return url;

  const pref=String(reader||'ask').toLowerCase();

  // MODE DEMANDER : ancien chemin qui fonctionnait.
  // Aucun package imposé => Android affiche les lecteurs PDF compatibles.
  if(pref==='ask'){
    return 'intent://drive.google.com/file/d/'+id+
      '/view#Intent;scheme=https;action=android.intent.action.VIEW;type=application/pdf;'+
      'S.browser_fallback_url='+encodeURIComponent(url)+';end';
  }

  // Pour ce test, les autres préférences restent volontairement sur
  // le chemin Drive stable. On les corrigera seulement après validation
  // du mode Demander.
  return 'intent://drive.google.com/file/d/'+id+
    '/view?usp=drivesdk#Intent;scheme=https;package=com.google.android.apps.docs;'+
    'S.browser_fallback_url='+encodeURIComponent(url)+';end';
}
function cdqV19OpenDrivePdfV2282(id){
  const pref=typeof cdqPdfReaderPreference==='function'
    ? cdqPdfReaderPreference()
    : 'ask';

  const a=document.createElement('a');
  a.href=cdqPdfDriveAppUrlV2283(id,pref);
  a.target='_blank';
  a.rel='noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();

  if(String(utilisateurCourantRole||'')!=='lecture'){
    fichierOuvertPourModification=id;
    sessionStorage.setItem('fichierEnModification',id);
    sessionStorage.setItem('ancienneDateModification',String((cdqDocumentMeta(id)||{}).dateModification||''));
    sessionStorage.setItem('momentModification',String(Date.now()));
  }
}
const cdqV19OldModify=window.modifierFichier;
window.modifierFichier=function(id){
  const meta=cdqDocumentMeta(id);

  if(meta&&meta.type==='GOOGLE_SHEETS'){
    cdqV19OpenOfflineSheet(id);
    return;
  }

  if(meta&&meta.type==='PDF'){
    if(navigator.onLine!==false){
      cdqV19OpenDrivePdfV2282(id);
